import { useCallback, useId, useRef, useState } from 'react';
// Предполагаемые экспорты runtime-слоя @jinx-ui/react: Slider, Switch, Select.
// Если имена в вашей сборке другие — переименуйте импорт, разметка не изменится.
import { Select, Slider, Switch } from '@jinx-ui/react';

export type Theme = 'brutal' | 'glass' | 'minimal';

export interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: string;
}

interface AppearanceSettingsScreenProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEMES: ReadonlyArray<{ value: Theme; label: string }> = [
  { value: 'brutal', label: 'Brutal' },
  { value: 'glass', label: 'Glass' },
  { value: 'minimal', label: 'Minimal' },
];

const FONTS = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const INITIAL: AppearanceSettings = {
  theme: 'brutal',
  scale: 100,
  dense: false,
  font: 'system',
};

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    ...INITIAL,
    ...defaultValue,
  });
  const themeButtons = useRef<Array<HTMLButtonElement | null>>([]);
  const scaleId = useId();
  const fontId = useId();

  const patch = useCallback(
    (part: Partial<AppearanceSettings>) => {
      setSettings((prev) => {
        const next = { ...prev, ...part };
        onChange?.(next);
        return next;
      });
    },
    [onChange],
  );

  const onThemeKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    const step =
      event.key === 'ArrowRight' || event.key === 'ArrowDown'
        ? 1
        : event.key === 'ArrowLeft' || event.key === 'ArrowUp'
          ? -1
          : 0;
    if (step === 0) return;
    event.preventDefault();
    const current = THEMES.findIndex((item) => item.value === settings.theme);
    const next = THEMES[(current + step + THEMES.length) % THEMES.length];
    patch({ theme: next.value });
    themeButtons.current[THEMES.indexOf(next)]?.focus();
  };

  const currentTheme = THEMES.find((item) => item.value === settings.theme);

  return (
    <section
      className="jx-surface jx-stack"
      style={{ gap: 'var(--jx-space-5)', padding: 'var(--jx-space-5)' }}
    >
      <header
        className="jx-row"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <h2 className="jx-title">Внешний вид</h2>
        <span className="jx-badge" aria-live="polite">
          Тема: {currentTheme?.label}
        </span>
      </header>

      <div className="jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
        <span className="jx-label" id={`${scaleId}-theme-label`}>
          Тема оформления
        </span>
        <div
          className="jx-segmented"
          role="radiogroup"
          aria-labelledby={`${scaleId}-theme-label`}
          onKeyDown={onThemeKeyDown}
          style={{ display: 'flex', gap: 'var(--jx-space-1)' }}
        >
          {THEMES.map((item, index) => {
            const active = item.value === settings.theme;
            return (
              <button
                key={item.value}
                ref={(node) => {
                  themeButtons.current[index] = node;
                }}
                type="button"
                role="radio"
                aria-checked={active}
                tabIndex={active ? 0 : -1}
                className={
                  active ? 'jx-segmented-item is-active' : 'jx-segmented-item'
                }
                onClick={() => patch({ theme: item.value })}
              >
                {item.label}
              </button>
            );
          })}
        </div>
      </div>

      <div className="jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
        <div
          style={{
            display: 'flex',
            alignItems: 'baseline',
            justifyContent: 'space-between',
            gap: 'var(--jx-space-3)',
          }}
        >
          <label className="jx-label" htmlFor={scaleId}>
            Масштаб интерфейса
          </label>
          <output className="jx-value" htmlFor={scaleId}>
            {settings.scale}%
          </output>
        </div>
        <Slider
          id={scaleId}
          min={80}
          max={140}
          step={5}
          value={settings.scale}
          onChange={(value: number) => patch({ scale: value })}
        />
      </div>

      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <span className="jx-stack" style={{ gap: 'var(--jx-space-1)' }}>
          <span className="jx-label">Плотная вёрстка</span>
          <span className="jx-hint">Меньше отступов, больше данных на экране</span>
        </span>
        <Switch
          checked={settings.dense}
          aria-label="Плотная вёрстка"
          onChange={(checked: boolean) => patch({ dense: checked })}
        />
      </div>

      <hr className="jx-divider" />

      <div className="jx-stack" style={{ gap: 'var(--jx-space-3)' }}>
        <h3 className="jx-subtitle">Ещё</h3>
        <div className="jx-stack" style={{ gap: 'var(--jx-space-2)' }}>
          <label className="jx-label" htmlFor={fontId}>
            Шрифт
          </label>
          <Select
            id={fontId}
            value={settings.font}
            options={FONTS}
            onChange={(value: string) => patch({ font: value })}
          />
        </div>
      </div>
    </section>
  );
}

